/**
 * Import named routes generated by the host with
 * `php artisan wayfinder:generate --path=resources/js/wayfinder`.
 */
export {
    index as workflowsIndex,
    create as workflowsCreate,
    store as workflowsStore,
    edit as workflowsEdit,
    update as workflowsUpdate,
    destroy as workflowsDestroy,
    duplicate as workflowsDuplicate,
    restore as workflowsRestore,
} from '@/wayfinder/routes/development/pipelines/workflows';

export {
    index as pipelinesIndex,
    store as pipelinesStore,
    update as pipelinesUpdate,
    destroy as pipelinesDestroy,
    restore as pipelinesRestore,
} from '@/wayfinder/routes/development/pipelines/workflow-pipelines';

export type WayfinderRoute = string | { url: string; method?: string };

export function routeUrl(route: WayfinderRoute): string {
    return typeof route === 'string' ? route : route.url;
}
